#include <stdio.h>
#include <assert.h>
#include "cp_host.h"
static unsigned calls;
static cp_result deny_cert(void *c,const uint8_t *p,size_t n){(void)c;(void)p;(void)n;++calls;return CP_E_UNAVAILABLE;}
static cp_result deny_digest(void *c,const uint8_t d[32],const uint8_t s[64]){(void)c;(void)d;(void)s;++calls;return CP_E_UNAVAILABLE;}
static cp_result deny_sap(void *c,const uint8_t k[32],const uint8_t p[32],const uint8_t *r,size_t n){(void)c;(void)k;(void)p;(void)r;(void)n;++calls;return CP_E_UNAVAILABLE;}
int main(void){
 cp_config c={0};c.profile_id=CP_PROFILE_IOS_24A446_RESEARCH;
 cp_availability a=cp_config_availability(&c);assert(a.result==CP_E_UNSUPPORTED && !a.implementation_available && !a.current_build_fidelity_established && !a.live_interoperability_tested);
 printf("{\"case\":\"current_missing_providers\",\"result\":%d,\"protocol_gaps\":%llu,\"provider_gaps\":%u,\"unresolved_contracts\":%u,\"available\":false}\n",a.result,(unsigned long long)a.missing_protocol,a.missing_providers,a.unresolved_provider_contracts);
 static const uint8_t id[]={1};c.local_id=id;c.local_id_n=1;c.setup_code=id;c.setup_code_n=1;c.certificate=deny_cert;c.verify_digest=deny_digest;c.sap=deny_sap;
 a=cp_config_availability(&c);assert(a.result==CP_E_UNSUPPORTED && a.missing_providers==0 && a.missing_protocol && a.unresolved_provider_contracts && !a.implementation_available && calls==0);
 printf("{\"case\":\"presence_does_not_verify\",\"result\":%d,\"protocol_gaps\":%llu,\"provider_gaps\":%u,\"unresolved_contracts\":%u,\"provider_calls\":%u,\"available\":false}\n",a.result,(unsigned long long)a.missing_protocol,a.missing_providers,a.unresolved_provider_contracts,calls);
 c.require_target_iap=true;a=cp_config_availability(&c);assert(a.missing_protocol&CP_GAP_RUNTIME_TUNNEL);assert(a.missing_providers&CP_PROVIDER_TUNNEL_CONTRACT);
 printf("{\"case\":\"target_tunnel_not_assumed\",\"result\":%d,\"protocol_gaps\":%llu,\"provider_gaps\":%u,\"available\":false}\n",a.result,(unsigned long long)a.missing_protocol,a.missing_providers);
 c=(cp_config){0};c.profile_id=CP_PROFILE_EXPERIMENTAL_OLD_PAIRED_SAP_V1;a=cp_config_availability(&c);assert(a.experimental && a.result==CP_E_UNAVAILABLE && !a.current_build_fidelity_established && !a.live_interoperability_tested);
 printf("{\"case\":\"legacy_not_production_ready\",\"result\":%d,\"experimental\":true,\"current_fidelity\":false,\"live\":false}\n",a.result);
 return 0;
}

